#include "fluxselection.h"
#include "fluxbrush.h"
#include <QFileInfo>
#include <QInputDialog>
#include <QLineEdit>
#include <QMouseEvent>
#include <QPainter>
#include <QPainterPath>
#include <QPointingDevice>
#include <QPolygonF>
#include <QResizeEvent>
